class View:
    def __init__(self):
        self.rows=[]
        self.notes={}
        self.loading=False
        self.error=None
        self.seq=0
        self.current_request_id=None

    def begin(self, query):
        self.seq+=1
        request_id = self.seq
        self.current_request_id = request_id
        self.rows=[]
        self.notes={}
        self.loading=True
        self.error=None
        return request_id

    def finish(self, request_id, rows):
        if self.current_request_id is None or self.current_request_id != request_id:
            return False

        self.rows = rows
        self.notes = {}
        for row in rows:
            job_id = row.get('job_id')
            note = row.get('note', '')
            if job_id is not None:
                self.notes[job_id] = note

        self.loading = False
        return True
